const items = $input.all();

const excludedTags = new Set([
  "script", "style", "noscript", "svg",
  "iframe", "form", "nav", "header", "footer"
]);

const excludedClasses = [
  "top-nav", "campus-nav", "navbar",
  "dropdown", "megamenu", "menu",
  "header-ul", "topnav-ul",
  "search-box", "search-mbl",
  "modal", "footer", "navbar-header"
];

const voidTags = new Set([
  "area", "base", "br", "col", "embed",
  "hr", "img", "input", "link", "meta",
  "param", "source", "track", "wbr"
]);

function removeUnwantedElements(html) {
  const regex = /<!--[\s\S]*?-->|<![^>]*>|<\/?[a-zA-Z][^>]*>/g;

  let result = "";
  let position = 0;
  const suppressed = [];

  for (const match of html.matchAll(regex)) {
    const token = match[0];
    const index = match.index;

    if (suppressed.length === 0) {
      result += html.slice(position, index);
    }

    position = index + token.length;

    const closing = token.match(/^<\s*\/\s*([\w:-]+)/);

    if (closing) {
      if (suppressed.length) {
        const tag = closing[1].toLowerCase();
        const found = suppressed.lastIndexOf(tag);

        if (found !== -1) {
          suppressed.length = found;
        }
      } else {
        result += token;
      }
      continue;
    }

    const opening = token.match(/^<\s*([\w:-]+)/);
    if (!opening) continue;

    const tag = opening[1].toLowerCase();
    const classMatch = token.match(/\bclass\s*=\s*["']([^"']*)["']/i);
    const classes = classMatch ? classMatch[1].toLowerCase() : "";

    const remove =
      excludedTags.has(tag) ||
      excludedClasses.some(name => classes.includes(name));

    const selfClosing =
      /\/\s*>$/.test(token) || voidTags.has(tag);

    if (suppressed.length) {
      if (!selfClosing) suppressed.push(tag);
    } else if (remove) {
      if (!selfClosing) suppressed.push(tag);
    } else {
      result += token;
    }
  }

  if (suppressed.length === 0) {
    result += html.slice(position);
  }

  return result;
}

function cleanText(html) {
  return removeUnwantedElements(html)
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(p|div|section|article|li|h[1-6]|tr)>/gi, "\n")
    .replace(/<[^>]*>/g, " ")
    .replace(/&#(\d+);/g, (_, n) =>
      String.fromCodePoint(Number(n))
    )
    .replace(/&#x([0-9a-f]+);/gi, (_, n) =>
      String.fromCodePoint(parseInt(n, 16))
    )
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&rsquo;/gi, "'")
    .replace(/&mdash;/gi, "-")
    .replace(/[ \t]+/g, " ")
    .replace(/ *\n */g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

return items
  .filter(item => item.json.statusCode === 200)
  .map(item => {
    const html = item.json.output || "";
    const titleMatch = html.match(
      /<title[^>]*>([\s\S]*?)<\/title>/i
    );

    const title = titleMatch
      ? cleanText(titleMatch[1])
      : item.json.topic;

    const content = cleanText(html);

    return {
      json: {
        title,
        topic: item.json.topic,
        source: item.json.source,
        source_url: item.json.url,
        content
      }
    };
  })
  .filter(item => item.json.content.length > 100);
